    N = logits.shape[1]
    if self.criterion == 'cross_entropy':
        return one_hot(labels, num=N)
    elif self.criterion == 'label_smooth_ce':
        val = float(self.ratio) / (N - 1)
        ret = torch.full_like(logits, val)
